mapper.select:
SELECT slot_code, usable_height, fork_height, destination_x, destination_y,
       destination_heading, status
FROM storage_slot WHERE slot_code = #{slotCode}

mapper.update:
UPDATE storage_slot
SET status='OCCUPIED', reserved_task_id=NULL, stored_cargo_id=#{storedCargoId}
WHERE slot_code=#{slotCode} AND status='RESERVED' AND reserved_task_id=#{reservedTaskId}
